 'A1: a*t^p*A^q + b*t^r*A^s': (lambda p: p[0]*t**p[1]*A**p[2]+p[3]*t**p[4]*A**p[5], 6),
 'B: a*t^p*(A-b)*(A-c)': (lambda p: p[0]*t**p[1]*(A-p[2])*(A-p[3]), 4),
 'C: a*t^p*A*lnA + b*t^q*A + c*t^r': (lambda p: p[0]*t**p[1]*A*np.log(A)+p[2]*t**p[3]*A+p[4]*t**p[5], 6),
